    if target is not None:
        tx, ty = target
        return [step_toward(sx, tx), step_toward(sy, ty)]

    # Fallbacks: pursue if possible, otherwise stay put.
    if opp_pos is not None:
        return [step_toward(sx, ox), step_toward(sy, oy)]
    return [0, 0]

